/* Splitter / linesiter state. Classes are declared `is native`
   with no user fields; the runtime supplies the real layout,
   stack-allocated value type (48 bytes). Both iterators share
   the same struct — linesiter leaves sep NULL — under a name of
   its own, so either type can be the only one a program uses. */
typedef struct {
    const char* src;
    uint64_t    src_len;
    const char* sep;
    uint64_t    sep_len;
    uint64_t    cursor;
    bool        done;
} z_sv_iter_t;

typedef z_sv_iter_t z_t7241_t;

typedef z_sv_iter_t z_t7334_t;


static z_t7241_t z_t84_split(
    const z_t84_t* self, const z_t84_t* sep);
static z_t7241_t z_t84_split(
    const z_t84_t* self, const z_t84_t* sep) {
    z_t7241_t s;
    s.src = self->data;
    s.src_len = self->size;
    s.sep = sep->data;
    s.sep_len = sep->size;
    s.cursor = 0;
    s.done = (sep->size == 0);
    return s;
}


static z_t7246_t z_t7241_call(z_t7241_t* s);
static z_t7246_t z_t7241_call(z_t7241_t* s) {
    z_t7246_t out = {0};
    if (s->done) {
        out.tag = Z_OPTION_STRINGVIEW_TAG_NONE;
        return out;
    }
    const char* start = s->src + s->cursor;
    uint64_t remaining = s->src_len - s->cursor;
    if (s->sep_len > remaining) {
        /* no more separators possible — return the tail */
        z_t84_t* boxed = (z_t84_t*)z_xmalloc(sizeof(z_t84_t));
        boxed->data = start;
        boxed->size = remaining;
        s->cursor = s->src_len;
        s->done = true;
        out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
        out.data = boxed;
        return out;
    }
    uint64_t scan_end = remaining - s->sep_len;
    for (uint64_t i = 0; i <= scan_end; i++) {
        if (memcmp(start + i, s->sep, s->sep_len) == 0) {
            z_t84_t* boxed = (z_t84_t*)z_xmalloc(sizeof(z_t84_t));
            boxed->data = start;
            boxed->size = i;
            s->cursor += i + s->sep_len;
            out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
            out.data = boxed;
            return out;
        }
    }
    /* no separator in remaining — final fragment */
    z_t84_t* boxed = (z_t84_t*)z_xmalloc(sizeof(z_t84_t));
    boxed->data = start;
    boxed->size = remaining;
    s->cursor = s->src_len;
    s->done = true;
    out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
    out.data = boxed;
    return out;
}


static z_t7334_t z_t84_lines(const z_t84_t* self);
static z_t7334_t z_t84_lines(const z_t84_t* self) {
    z_t7334_t s;
    s.src = self->data;
    s.src_len = self->size;
    s.sep = NULL;
    s.sep_len = 0;
    s.cursor = 0;
    s.done = (self->size == 0);
    return s;
}


static z_t7246_t z_t7334_call(z_t7334_t* s);
static z_t7246_t z_t7334_call(z_t7334_t* s) {
    z_t7246_t out = {0};
    if (s->done) {
        out.tag = Z_OPTION_STRINGVIEW_TAG_NONE;
        return out;
    }
    const char* start = s->src + s->cursor;
    uint64_t remaining = s->src_len - s->cursor;
    uint64_t i = 0;
    while (i < remaining && start[i] != '\n') i++;
    uint64_t line_len = i;
    if (line_len > 0 && start[line_len - 1] == '\r') line_len--;
    z_t84_t* boxed = (z_t84_t*)z_xmalloc(sizeof(z_t84_t));
    boxed->data = start;
    boxed->size = line_len;
    if (i == remaining) {
        s->cursor = s->src_len;
        s->done = true;
    } else {
        s->cursor += i + 1;
        if (s->cursor >= s->src_len) s->done = true;
    }
    out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
    out.data = boxed;
    return out;
}


